        ['[5]', 'Entanglement renormalization', 'MERA ansatz'],
        ['[6], [7]', 'Deutsch–Jozsa and Shor algorithms', 'Study 1 circuits'],
        ['[8]', 'quimb library', 'MPS/TT simulation engine'],
        ['[9]', 'Simple update for PEPS', 'Imaginary-time evolution'],
